    "safety.incident_created": "Осол амжилттай мэдээлэгдсэн",
    "safety.incident_desc_placeholder": "Юу болсныг тайлбарлана уу...",
    "safety.incident_type_environmental": "Алдагдал эсвэл ялгаралт",
